import { ActionMetrics } from '../../proto_utils/sim_result.js';
import { sum } from '../../utils.js';

import { SimResultData } from './result_component.js';

// The scale used by the damage/healing bars: `total` is the denominator for the
// share-of-total percentage, and `max` is the largest single row (so the biggest
// ability fills the bar). Both are computed across the player's ENTIRE damage
// (melee + spell + pets), so percentages sum to 100% across the split tables,
// matching the single combined table used in Cataclysm.
export interface BarScale {
	max: number;
	total: number;
}

function barScaleFromActions(actions: Array<ActionMetrics>): BarScale {
	const merged = ActionMetrics.groupById(actions).map(group => ActionMetrics.merge(group, true));
	const values = merged.map(metric => metric.damage);
	return {
		max: values.length ? Math.max(...values) : 0,
		total: sum(values),
	};
}

// Totals across all of the player's (and its pets') damage actions.
export function playerDamageBarScale(resultData: SimResultData): BarScale {
	const players = resultData.result.getPlayers(resultData.filter);
	if (players.length != 1) {
		return { max: 0, total: 0 };
	}
	const player = players[0];
	const units = [player, ...player.pets];
	const actions = units.flatMap(unit => [...unit.getMeleeActions(), ...unit.getSpellActions()].map(action => action.forTarget(resultData.filter)));
	return barScaleFromActions(actions);
}

// Totals across all damage taken by the player (every target's melee + spell actions).
export function damageTakenBarScale(resultData: SimResultData): BarScale {
	const targets = resultData.result.getTargets(resultData.filter);
	const actions = targets.flatMap(target => [...target.getMeleeActions(), ...target.getSpellActions()].map(action => action.forTarget(resultData.filter)));
	return barScaleFromActions(actions);
}
